CREATE POLICY "Room reference owner upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'room-references' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Room reference owner read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'room-references' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Room reference owner delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'room-references' AND (storage.foldername(name))[1] = auth.uid()::text);